D=$(mktemp -d) && cat > "$D/perobj.py" <<'PY'
import json, collections
from pathlib import Path
import jsonschema
REPO=Path("/home/tamask/github/KONI")
canon=json.load(open(REPO/"data/canon.json",encoding="utf-8"))
schema=json.load(open(REPO/"schema/canon.schema.json",encoding="utf-8"))

auth_pat = schema["patternProperties"]["^[0-9]{4}$"]
works_pat = auth_pat["properties"]["works"]["patternProperties"]["^[0-9]{3}$"]

def mk(subschema, defs=None):
    s=dict(subschema)
    if defs: s={**s, **defs}
    return s

auth_fail=collections.Counter(); work_fail=collections.Counter()
auth_fail_ids=[]; work_fail_ids=[]
author_schema = {"type":"object",
    "required": auth_pat["required"],
    "additionalProperties": auth_pat["additionalProperties"],
    "properties": auth_pat["properties"]}
# works sub-schema reused inside author; validate author with works emptied to isolate,
# then validate each work with the work schema.
author_schema_no_works = json.loads(json.dumps(author_schema))
author_schema_no_works["properties"]["works"]={"type":"object"}
work_schema = {"type":"object",
    "required": works_pat["required"],
    "additionalProperties": works_pat["additionalProperties"],
    "properties": works_pat["properties"]}

n_a=n_w=0
for aid,a in canon.items():
    n_a+=1
    try:
        jsonschema.validate(a, author_schema_no_works)
    except jsonschema.ValidationError as e:
        auth_fail[str(e.message)]+=1
        if len(auth_fail_ids)<10: auth_fail_ids.append((aid, str(e.message)))
    works=a.get("works") or {}
    for wid,w in works.items():
        n_w+=1
        try:
            jsonschema.validate(w, work_schema)
        except jsonschema.ValidationError as e:
            work_fail[str(e.message)]+=1
            if len(work_fail_ids)<10: work_fail_ids.append((f"{aid}.{wid}", str(e.message)))

print("authors validated:",n_a," works validated:",n_w)
print("AUTHOR per-object failures:",sum(auth_fail.values()),"distinct msgs:",len(auth_fail))
for m,c in auth_fail.most_common(): print("   ",c,"x",m)
print("WORK per-object failures:",sum(work_fail.values()),"distinct msgs:",len(work_fail))
for m,c in work_fail.most_common(): print("   ",c,"x",m)
print("sample author ids:",auth_fail_ids)
print("sample work ids:",work_fail_ids)
PY
PYTHONPATH=/home/tamask/github/KONI/scripts python3 "$D/perobj.py"; echo "EXIT=$?"

D=$(mktemp -d) && cat > "$D/hand.py" <<'PY'
"""Hand-rolled stdlib-only draft-07 subset validator (independent of jsonschema)."""
import json, re
from pathlib import Path
REPO=Path("/home/tamask/github/KONI")
canon=json.load(open(REPO/"data/canon.json",encoding="utf-8"))
S=json.load(open(REPO/"schema/canon.schema.json",encoding="utf-8"))

TYPE={"object":dict,"array":list,"string":str,"boolean":bool,"null":type(None),
      "integer":int,"number":(int,float)}

def check(inst, sch, path, errs):
    if not isinstance(sch,bool) and "type" in sch:
        t=sch["type"]; ts=t if isinstance(t,list) else [t]
        ok=False
        for tt in ts:
            py=TYPE[tt]
            if tt=="boolean" and isinstance(inst,bool): ok=True; break
            if tt in ("integer","number") and isinstance(inst,bool): continue
            if isinstance(inst,py): ok=True; break
        if not ok:
            errs.append((path,f"type: expected {ts}, got {type(inst).__name__}"))
            return
    if "pattern" in sch and isinstance(inst,str):
        if not re.search(sch["pattern"],inst):
            errs.append((path,f"pattern {sch['pattern']!r} not matched by {inst!r}"))
    if "minLength" in sch and isinstance(inst,str) and len(inst)<sch["minLength"]:
        errs.append((path,f"minLength {sch['minLength']} violated"))
    if "minItems" in sch and isinstance(inst,list) and len(inst)<sch["minItems"]:
        errs.append((path,f"minItems {sch['minItems']} violated"))
    if "items" in sch and isinstance(inst,list):
        for i,v in enumerate(inst): check(v,sch["items"],f"{path}[{i}]",errs)
    if isinstance(inst,dict):
        props=sch.get("properties",{}); pats=sch.get("patternProperties",{})
        addl=sch.get("additionalProperties",True)
        for k in sch.get("required",[]):
            if k not in inst: errs.append((path,f"required property {k!r} missing"))
        for k,v in inst.items():
            matched=False
            if k in props: check(v,props[k],f"{path}.{k}",errs); matched=True
            for pat,ps in pats.items():
                if re.search(pat,k): check(v,ps,f"{path}.{k}",errs); matched=True
            if not matched and addl is False:
                errs.append((path,f"additionalProperties: {k!r} not allowed"))

errs=[]
check(canon,S,"$",errs)
print("HAND-ROLLED stdlib validator errors:",len(errs))
for e in errs[:20]: print("  ",e)
PY
python3 "$D/hand.py"; echo "EXIT=$?"

